{"anchor_ids":[],"block_type":"paragraph","heading_level":null,"image_align":null,"image_alt":null,"image_caption":null,"links":[],"list_items":null,"list_ordered":null,"media_id":null,"page_id":"page-99086b24-3a6e-4817-b05a-9617a417b886","position":61,"table_caption":null,"table_rows":null,"text":"במידה ויש צורך בויזה ולא התקבלה ויזה במועד יחויב הלקוח בדמי ביטול על פי מדיניות הביטול שלנו."},
