{"anchor_ids":[],"block_type":"paragraph","heading_level":null,"image_align":null,"image_alt":null,"image_caption":null,"links":[],"list_items":null,"list_ordered":null,"media_id":null,"page_id":"page-99086b24-3a6e-4817-b05a-9617a417b886","position":67,"table_caption":null,"table_rows":null,"text":"יש לוודא את תנאי הכבודה בכל טיול. אנו נציין בכל טיול מה כולל וכל שמעבר למשקל הכלול או למספר המזוודות יהיה על חשבון הלקוח."},
